import{_ as a,c as n,o as s,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Credentialing Assistance","description":"","frontmatter":{"title":"Credentialing Assistance"},"headers":[],"relativePath":"general/credentialing-assistance.md","filePath":"general/credentialing-assistance.md","lastUpdated":null}'),t={name:"general/credentialing-assistance.md"};function r(l,e,c,d,o,p){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="credentialing-assistance" tabindex="-1">Credentialing Assistance <a class="header-anchor" href="#credentialing-assistance" aria-label="Permalink to &quot;Credentialing Assistance&quot;">​</a></h1><h2 id="what-is-credentialing-assistance-ca" tabindex="-1">What is Credentialing Assistance (CA) <a class="header-anchor" href="#what-is-credentialing-assistance-ca" aria-label="Permalink to &quot;What is Credentialing Assistance (CA)&quot;">​</a></h2><p>Credentialing Assistance (CA) is a program designed to help service members obtain professional certifications and credentials that align with their career goals, enhancing their skills and employability.</p><h2 id="what-is-sans" tabindex="-1">What is SANS <a class="header-anchor" href="#what-is-sans" aria-label="Permalink to &quot;What is SANS&quot;">​</a></h2><p>SANS (SysAdmin, Audit, Network, and Security) Institute is a trusted organization that provides advanced training and certifications in cybersecurity, equipping professionals with practical skills to protect and defend networks and systems.</p><h2 id="recommended-certification-using-credentialing-assistance-ca" tabindex="-1">Recommended Certification using Credentialing Assistance (CA) <a class="header-anchor" href="#recommended-certification-using-credentialing-assistance-ca" aria-label="Permalink to &quot;Recommended Certification using Credentialing Assistance (CA)&quot;">​</a></h2><p>Check out the recommended <a href="https://www.sans.org/cyber-security-skills-roadmap/" target="_blank" rel="noreferrer">SANS Roadmap</a>.</p><p><a href="#">Cybersecurity Skills Roadmap</a></p><p>Recommended Certification: <a href="https://www.sans.org/cyber-security-courses/hacker-techniques-incident-handling/" target="_blank" rel="noreferrer">SEC504: Hacker Tools, Techniques, and Incident Handling: GIAC Certified Incident Handler (GCIH)</a>.</p><h3 id="use-ta-for-sans-credentialing-assistance-ca" tabindex="-1">Use TA for SANS Credentialing Assistance (CA) <a class="header-anchor" href="#use-ta-for-sans-credentialing-assistance-ca" aria-label="Permalink to &quot;Use TA for SANS Credentialing Assistance (CA)&quot;">​</a></h3><ul><li><p>Create a SANS Account at <a href="https://www.sans.org/account/create/" target="_blank" rel="noreferrer">SANS Account Creation</a> using your .mil email.</p></li><li><p>Order On-Demand SANS Training at <a href="https://www.sans.org/ondemand/" target="_blank" rel="noreferrer">SANS On-Demand</a>.</p><ul><li>Select your desired training and proceed to checkout. <ul><li>Recommendation: <a href="https://www.sans.org/cyber-security-courses/hacker-techniques-incident-handling/" target="_blank" rel="noreferrer">GIAC Certified Incident Handler (GCIH)</a>.</li></ul></li><li>Select “Pay by Phone or Multiple Credit Cards.”</li><li>Note your order number.</li></ul></li><li><p>Email for further assistance and discount details:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><p>I request to have the discount down to $4k (the total annual amount for CA) for the following training:</p><p><em>Email being Forwarded to SANS</em></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>- Complete the ArmyIgnitED portion after receiving the updated SANS quote:</span></span>
<span class="line"><span>  - Log in to [ArmyIgnitED](https://www.armyignited.com/app/).</span></span>
<span class="line"><span>  - Request Credentialing Assistance at [Credentialing Assistance Request](https://www.armyignited.com/app/student/credential-paths/request).</span></span>
<span class="line"><span>    - Select “Other for MOS.”</span></span>
<span class="line"><span>    - Search for Pathway: GIAC Certified Incident Handler (GCIH) if using the above recommendation.</span></span>
<span class="line"><span>    - Upload the quote received from the SANS email.</span></span>
<span class="line"><span>  - Profit!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Assistance]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div>`,14)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
